(function(){
  let inited=false;
  let webs=[];
  let particles=[];
  let start=null;

  function makeWeb(cx,cy,scale){
    const numRadials = 9;
    const drops=[];
    for(let i=0;i<numRadials;i++){
      const angle=(Math.PI*2*i)/numRadials + Math.random()*0.15;
      const len= scale;
      const numDrops=2+Math.floor(Math.random()*2);
      for(let j=1;j<=numDrops;j++){
        const dist= len*(j/(numDrops+1))*(0.6+Math.random()*0.4);
        drops.push({angle,dist,r:2.5+Math.random()*4.5,phase:Math.random()*Math.PI*2,speed:0.25+Math.random()*0.35});
      }
    }
    return {cx,cy,numRadials,radLen:scale,drops,rings:3+Math.floor(Math.random()*2)};
  }

  function init(){
    const w=W(), h=H();
    webs=[
      makeWeb(w*0.86, h*0.16, Math.min(w,h)*0.5),
      makeWeb(w*0.1, h*0.88, Math.min(w,h)*0.32)
    ];
    particles=[];
    for(let i=0;i<50;i++){
      particles.push({
        x:Math.random()*w, y:Math.random()*h,
        r:0.6+Math.random()*1.6,
        a:0.15+Math.random()*0.45,
        vy:-(0.04+Math.random()*0.08),
        vx:(Math.random()-0.5)*0.04,
        ph:Math.random()*Math.PI*2
      });
    }
    inited=true;
  }

  function hexToRgba(hex,alpha){
    const h=hex.replace('#','');
    const r=parseInt(h.substring(0,2),16);
    const g=parseInt(h.substring(2,4),16);
    const b=parseInt(h.substring(4,6),16);
    return 'rgba('+r+','+g+','+b+','+alpha+')';
  }

  function drawWeb(web,t,colorLine,colorDrop){
    const cx=web.cx, cy=web.cy, numRadials=web.numRadials, radLen=web.radLen, drops=web.drops, rings=web.rings;
    ctx.save();
    ctx.lineWidth=1;
    ctx.strokeStyle=hexToRgba(colorLine,0.22);
    for(let i=0;i<numRadials;i++){
      const angle=(Math.PI*2*i)/numRadials;
      const ex=cx+Math.cos(angle)*radLen;
      const ey=cy+Math.sin(angle)*radLen;
      ctx.beginPath();
      ctx.moveTo(cx,cy);
      ctx.lineTo(ex,ey);
      ctx.stroke();
    }
    for(let k=1;k<=rings;k++){
      const rr=radLen*(k/(rings+1));
      ctx.beginPath();
      for(let i=0;i<=numRadials;i++){
        const angle=(Math.PI*2*i)/numRadials;
        const wob = Math.sin(t*0.3 + i + k)*rr*0.02;
        const px=cx+Math.cos(angle)*(rr+wob);
        const py=cy+Math.sin(angle)*(rr+wob);
        if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
      }
      ctx.stroke();
    }
    ctx.restore();

    for(const d of drops){
      const wob = Math.sin(t*d.speed+d.phase)*3;
      const dist=d.dist+wob;
      const x=cx+Math.cos(d.angle)*dist;
      const y=cy+Math.sin(d.angle)*dist;
      const glow = 0.55+0.45*Math.sin(t*d.speed*1.3+d.phase);
      const grad = ctx.createRadialGradient(x-d.r*0.3,y-d.r*0.3,0,x,y,d.r*2.2);
      grad.addColorStop(0, hexToRgba('#ffffff', 0.9*glow));
      grad.addColorStop(0.35, hexToRgba(colorDrop, 0.55*glow));
      grad.addColorStop(1, hexToRgba(colorDrop,0));
      ctx.save();
      ctx.shadowColor = hexToRgba(colorDrop,0.6);
      ctx.shadowBlur = d.r*2.5;
      ctx.fillStyle=grad;
      ctx.beginPath();
      ctx.arc(x,y,d.r,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    }
  }

  function frame(now){
    if(!start) start=now;
    const t=(now-start)/1000;
    const w=W(), h=H();
    if(!inited) init();
    ctx.clearRect(0,0,w,h);

    drawWeb(webs[0], t, PALETTE[2], PALETTE[0]);
    drawWeb(webs[1], t, PALETTE[2], PALETTE[1]);

    for(const p of particles){
      p.y += p.vy;
      p.x += p.vx + Math.sin(t*0.5+p.ph)*0.05;
      if(p.y< -10){ p.y = h+10; p.x=Math.random()*w; }
      const a = p.a*(0.6+0.4*Math.sin(t*0.8+p.ph));
      ctx.beginPath();
      ctx.fillStyle = hexToRgba(PALETTE[1], a);
      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fill();
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
